<?php require_once __DIR__ . '/../../includes/layout.php'; require_role(['Parent','Admin']); $parent=row('SELECT * FROM parents WHERE user_id=?',[$_SESSION['user_id']]); $child=$parent?row('SELECT s.*,u.full_name FROM students s JOIN users u ON u.id=s.user_id WHERE s.id=?',[$parent['student_id']]):null; render_header('Parent Monitoring'); ?><div class="page-title"><div><h1>Parent Monitoring</h1><p>Monitor student grades, attendance and alerts.</p></div></div><?php if($child): ?><div class="row g-3 mb-4"><?php card_stat('Student',$child['full_name'],'fa-child','primary',$child['student_no']); card_stat('GPA',number_format($child['gpa'],2),'fa-ranking-star','success','Current'); card_stat('Attendance',$child['attendance_rate'].'%','fa-calendar-check','warning','Overall'); card_stat('Risk',$child['risk_level'],'fa-triangle-exclamation','danger','Academic indicator'); ?></div><div class="row g-4"><div class="col-lg-6"><div class="panel"><div class="panel-title">Grades</div><table class="table"><tbody><?php foreach(rows('SELECT g.*,sub.code FROM grades g JOIN subjects sub ON sub.id=g.subject_id WHERE g.student_id=?',[$child['id']]) as $g): ?><tr><td><?= e($g['code']) ?></td><td><?= e($g['gpa']) ?></td><td><?= e($g['remarks']) ?></td></tr><?php endforeach; ?></tbody></table></div></div><div class="col-lg-6"><div class="panel"><div class="panel-title">Recent Attendance</div><?php foreach(rows('SELECT * FROM attendance WHERE student_id=? ORDER BY date DESC LIMIT 8',[$child['id']]) as $a): ?><div class="d-flex justify-content-between border-bottom py-2"><span><?= e($a['date']) ?> • <?= e($a['method']) ?></span><span class="badge bg-primary"><?= e($a['status']) ?></span></div><?php endforeach; ?></div></div></div><?php else: ?><div class="alert alert-warning">No linked student yet. Contact the administrator.</div><?php endif; ?><?php render_footer(); ?>
